import{_ as e,o as a,c as l,a2 as i}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"项目状态","description":"Hearth 的文档与项目状态、已完成内容、尚未开始部分与下一阶段计划。","frontmatter":{"title":"项目状态","description":"Hearth 的文档与项目状态、已完成内容、尚未开始部分与下一阶段计划。","outline":[2,3]},"headers":[],"relativePath":"guide/project-status.md","filePath":"guide/project-status.md","lastUpdated":1793752688000}'),r={name:"guide/project-status.md"};function o(d,t,h,n,s,c){return a(),l("div",null,[...t[0]||(t[0]=[i('<p class="eyebrow">PROJECT STATUS</p><h1 id="项目状态" tabindex="-1">项目状态 <a class="header-anchor" href="#项目状态" aria-label="Permalink to &quot;项目状态&quot;">​</a></h1><p class="lead">Hearth 目前处于规格与路线图阶段。仓库已经包含完整的产品、架构、安全、评估和交付计划，但实现尚未开始。</p><h2 id="文档与项目状态" tabindex="-1">文档与项目状态 <a class="header-anchor" href="#文档与项目状态" aria-label="Permalink to &quot;文档与项目状态&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>状态</th></tr></thead><tbody><tr><td>文档来源</td><td>产品、架构、安全与交付路线图整理</td></tr><tr><td>仓库</td><td><code>hearthproject/hearth-os</code></td></tr><tr><td>阶段</td><td>Specification &amp; planning</td></tr><tr><td>实现</td><td>尚未开始</td></tr><tr><td>下一个里程碑</td><td>Stage 0：产品真相、原型、协议与评测基线</td></tr><tr><td>许可证</td><td>Apache-2.0</td></tr></tbody></table><h2 id="已经完成" tabindex="-1">已经完成 <a class="header-anchor" href="#已经完成" aria-label="Permalink to &quot;已经完成&quot;">​</a></h2><ul><li>产品定义、非目标与首选用户；</li><li>八类任务覆盖、自主级别与“完成”的定义；</li><li>七个平面、领域实体、事件、执行器与回执协议；</li><li>入口、控制面、持久执行、执行器和人工接管设计；</li><li>执行安全、记忆、进化、Token 经济、前端与移动体验；</li><li>安全、隐私、威胁模型和评估体系；</li><li>Stage 0–6 产品路线图与从 0 到 100 的渐进开发计划；</li><li>工程结构、风险、Kill Criteria、ADR 索引与附录；</li><li>可部署的中英双语文档站。</li></ul><h2 id="尚未开始" tabindex="-1">尚未开始 <a class="header-anchor" href="#尚未开始" aria-label="Permalink to &quot;尚未开始&quot;">​</a></h2><ul><li>可运行的 <code>hearthd</code>、<code>hearth</code> CLI 和 Web 界面；</li><li>Stage 0 可点击原型与真实数据契约；</li><li>Codex Executor 的第一个真实切片；</li><li>Connector、Browser、GUI、Document/Data 执行器；</li><li>Memory OS、Evolution OS 与多设备同步。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>Stage 0 的目标不是“写更多文档”，而是把产品、交互、协议和验收钉住：</p><ol><li>选定第一个高频、低外部风险的任务族；</li><li>产出可点击的端到端 Web 原型；</li><li>为每个 UI 状态定义投影字段和主动作；</li><li>固化 Event、Task、Run、Executor、Approval、Receipt 的 schema v0；</li><li>建立评测任务集、验证器和威胁模型基线。</li></ol><p>Stage 0 的退出条件、增量清单和验收模板见<a href="/hearth-os/delivery/development-plan.html">开发计划</a>。</p><h2 id="如何跟进" tabindex="-1">如何跟进 <a class="header-anchor" href="#如何跟进" aria-label="Permalink to &quot;如何跟进&quot;">​</a></h2><ul><li>阅读<a href="/hearth-os/delivery/roadmap.html">分阶段产品路线图</a>了解能力门槛；</li><li>阅读<a href="/hearth-os/delivery/development-plan.html">从 0 到 100 开发计划</a>了解第一段实现顺序；</li><li>关注仓库提交与 Issue；</li><li>如果要参与文档或实现，请先读<a href="/hearth-os/reference/contributing.html">贡献与文档维护</a>。</li></ul>',15)])])}const m=e(r,[["render",o]]);export{u as __pageData,m as default};
